sys_script.script:
//MSSCUSTODY-3326 : Bulk Operations - Update case type to No Open case if no cases are open for a trade.
(function executeRule(current, previous /*null when async*/ ) {



    //check if there are any active cases
    var getCaseDetails = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
    getCaseDetails.addEncodedQuery('trade_id.sys_idSTARTSWITH' + current.trade_id.sys_id + '^stateIN1,10,2,18^sys_id!=' + current.sys_id);
    getCaseDetails.orderByDesc('sys_created_on');
    getCaseDetails.query();
    if (!getCaseDetails.next()) {
        var getTradeRec = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        getTradeRec.get(current.trade_id.sys_id);
        getTradeRec.case_type = 'no_open_case';
        getTradeRec.update();
    }


    /*
    //comment
    //When Real trade's case changes, update Trade's case Type to 'No Open Case'
    if (current.state.changesTo('Closed Complete') || current.state.changesTo('Cancelled') || current.state.changesTo('Closed Rejected')) {

        var caseGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_case');
        caseGR.addEncodedQuery('trade_id.sys_id=' + current.trade_id + '^active=true');
        caseGR.query();
        if (!caseGR.next()) {
            //gs.info('In BR to update case type'+current.trade_id.sys_id);
            var tradeGR = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
            if (tradeGR.get(current.trade_id.sys_id)) {
                tradeGR.setWorkflow(false);
                tradeGR.setValue('case_type', 'no_open_case'); //no active case
                tradeGR.update();
            }
        }
    }

    //MSSCUSTODY-3611 When dummy trade's case gets transferred to real trade, set dummy trade's case type to 'No Open Case'.
    if (current.trade_id.changes && previous.trade_id != '') {
        var tradeGR2 = new GlideRecord('x_hsb11_mss_c_proc_mss_custody_trade');
        if (tradeGR2.get(previous.trade_id)) {
            tradeGR2.setWorkflow(false);
            tradeGR2.setValue('case_type', 'no_open_case'); //no active case
            tradeGR2.update();
        }
    }

	*/

})(current, previous);
